func (repository mockListItemRepository) BulkAdd(ctx context.Context, userID, listID int64, input []items.ListItem) (*items.CollectionResult, error) {
	result := &items.CollectionResult{Order: []items.OrderedItem{}}
	for _, item := range input {
		item.ListId = listID
		err := repository.createItem(ctx, userID, &item)
		if errors.Is(err, items.ErrItemExists) {
			result.Skipped = append(result.Skipped, item.ProblemId)
			continue
		}
		if err != nil {
			return nil, err
		}
		result.Added = append(result.Added, item)
	}
	for _, item := range repository.items[listID] {
		result.Order = append(result.Order, items.OrderedItem{ProblemID: item.ProblemId, Position: item.Position})
	}
	sort.Slice(result.Order, func(i, j int) bool { return result.Order[i].Position < result.Order[j].Position })
	return result, nil
}

func (repository mockListItemRepository) MoveItems(ctx context.Context, userID, listID int64, moves []items.Move) (*items.CollectionResult, error) {
	stored, err := repository.GetItems(ctx, userID, listID)
	if err != nil {
		return nil, err
	}
	order := []items.OrderedItem{}
	for _, item := range stored {
		order = append(order, items.OrderedItem{ProblemID: item.ProblemId, Position: item.Position})
	}
	order, rebalanced, err := items.ApplyMoves(order, moves)
	if err != nil {
		return nil, err
	}
	for _, entry := range order {
		item := repository.items[listID][entry.ProblemID]
		item.Position = entry.Position
		repository.storeItem(item)
	}
	return &items.CollectionResult{Order: order, Rebalanced: rebalanced}, nil
}

func (repository mockListItemRepository) BulkRemove(ctx context.Context, userID, listID int64, ids []string) (*items.CollectionResult, error) {
	for _, id := range ids {
		if err := repository.deleteItem(ctx, userID, &items.ListItem{ListId: listID, ProblemId: id}); err != nil {
			return nil, err
		}
	}
	return &items.CollectionResult{Order: []items.OrderedItem{}}, nil
}
